<?php require_once __DIR__.'/auth.php'; require_admin(); $pdo=db(); if(isset($_GET['status'],$_GET['id'])){ if (!csrf_check()) { exit('Invalid or expired request. Go back and try again.'); } $allowedStatus=['new','read','replied','closed']; $status=in_array($_GET['status'],$allowedStatus,true)?$_GET['status']:'new'; $pdo->prepare('UPDATE enquiries SET status=? WHERE id=?')->execute([$status,(int)$_GET['id']]);header('Location: enquiries.php');exit;} $items=$pdo->query('SELECT * FROM enquiries ORDER BY created_at DESC')->fetchAll(); $tok=csrf_token(); ?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enquiries — Admin</title><meta name="robots" content="noindex, nofollow"><link href="https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Karla:wght@400;500;700&family=IBM+Plex+Mono:wght@400;500&display=swap" rel="stylesheet"><link rel="stylesheet" href="../assets/css/admin.css"></head><body><div class="top"><b>Strata &amp; Beam Admin — Enquiries</b><a href="index.php">Dashboard</a></div><div class="wrap"><a href="index.php" class="muted">&larr; Dashboard</a><h1>Project Enquiries</h1><?php if(empty($items)):?><p class="muted" style="padding:20px 0;">No enquiries yet — they'll show up here as soon as someone submits the contact form.</p><?php endif;?><?php foreach($items as $x):?><div class="item <?php echo $x['status']==='new'?'new':'';?>"><h3><?php echo htmlspecialchars($x['name']);?> &mdash; <?php echo htmlspecialchars($x['service']);?><?php if($x['status']==='new'):?><span class="badge-new">New</span><?php endif;?></h3><p><b>Email:</b> <?php echo htmlspecialchars($x['email']);?> &nbsp; <b>Phone:</b> <?php echo htmlspecialchars($x['phone']??'');?></p><p><?php echo nl2br(htmlspecialchars($x['message']));?></p><small class="muted"><?php echo htmlspecialchars($x['created_at']);?> &middot; Status: <?php echo htmlspecialchars($x['status']);?></small><div class="actions"><a class="btn outline" href="?id=<?php echo $x['id'];?>&status=read&csrf_token=<?php echo htmlspecialchars($tok);?>">Mark Read</a><a class="btn outline" href="?id=<?php echo $x['id'];?>&status=replied&csrf_token=<?php echo htmlspecialchars($tok);?>">Replied</a><a class="btn outline" href="?id=<?php echo $x['id'];?>&status=closed&csrf_token=<?php echo htmlspecialchars($tok);?>">Close</a></div></div><?php endforeach;?></div></body></html>
